const form = $('GEO Form').first().json;
const raw = String($input.first().json.data || '');
const clean = raw.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ');
const title = (clean.match(/<title[^>]*>([\s\S]*?)<\/title>/i)||[])[1]||'';
const meta = (clean.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)/i)||[])[1]||'';
const text = clean.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,8000);

const tierGuide = {
 'Tier 1: Executive & VIP Corporate Gifting': 'Buyers: HR heads, PAs, procurement, C-suite assistants. Topics: luxury corporate gifts, Ramadan/Eid/National Day gifting, VIP client gifts, branded premium hampers, bulk orders.',
 'Tier 2: Hospitality, Majlis & Boutique Hotel': 'Buyers: hotel GMs, F&B/guest-experience managers, majlis owners, interior buyers. Topics: guest amenities, in-room scent, majlis hospitality, boutique hotel experience, Arabic hospitality.',
 'Tier 3: Healthcare, Spas & Premium Medical Clinics': 'Buyers: clinic/spa owners, procurement, patient-experience managers. Topics: spa products, clinic ambience, premium patient experience, aromatherapy, wellness retail.',
 'Tier 4: Corporate Wellness & Interior Architecture': 'Buyers: facility managers, interior architects, HR wellbeing leads, developers. Topics: office wellness, scent branding, lobby/interior design, fit-out specifications.'
};

const market = form['Market'];
const lang = form['Language'];
const tier = form['Tier'];
const brand = form['Brand Name'] || title;

const system = 'You are a GEO (Generative Engine Optimization) strategist. You write realistic questions that real buyers type into AI engines (ChatGPT, Perplexity, Gemini, Claude, Google AI Overviews). Return ONLY valid JSON, no markdown, no commentary.';

const user = `BRAND: ${brand}
WEBSITE: ${form['Website URL']}
SITE TITLE: ${title}
META: ${meta}
SITE CONTENT (excerpt): ${text}

SELECTED TIER: ${tier}
TIER GUIDE: ${tierGuide[tier] || ''}
MARKET: ${market}
LANGUAGE: ${lang} (if "English + Arabic", make 5 English and 5 Arabic prompts)

TASK: Write exactly 10 prompts a buyer in ${market} would ask an AI engine, based on what this website actually sells.
Distribution:
- 2 x "Brand Direct Queries" (segment: Brand)
- 3 x "KSA Category Intent" (adapt the location to ${market}; segment: Category benchmark)
- 2 x "Executive Gifting" (segment: Non-brand)
- 3 x "Problem-Solution" (segment: Non-brand)
Rules: Non-brand and category prompts must NOT name the brand. Make them natural, specific, conversational, with city/market and seasonal or cultural context where relevant. Vary icp_search_type and keyword_intent.

Return JSON: {"prompts":[{"category":"","icp_search_type":"Commercial|Seasonal|Cultural|Comparison|Direct answer","keyword_intent":"Informational|Commercial|Transactional","market":"UAE|KSA|GCC|Global","language":"English|Arabic","segment":"Non-brand|Category benchmark|Brand","target_keyword":"","prompt_text":""}]}`;

return [{ json: {
  brand, website: form['Website URL'], tier, market,
  body: { model: 'claude-sonnet-4-6', max_tokens: 4000, system, messages: [{ role:'user', content: user }] }
}}];

const ctx = $('Build Prompt').first().json;
let txt = ($input.first().json.content || []).map(c => c.text || '').join('');
txt = txt.replace(/```json|```/g,'').trim();
const data = JSON.parse(txt);
const runId = Date.now().toString(36);
return data.prompts.map((p, i) => ({ json: {
  prompt_id: `${runId}-${String(i+1).padStart(2,'0')}`,
  created_at: new Date().toISOString(),
  brand: ctx.brand,
  website: ctx.website,
  tier: ctx.tier,
  category: p.category,
  icp_search_type: p.icp_search_type,
  keyword_intent: p.keyword_intent,
  market: p.market,
  language: p.language,
  segment: p.segment,
  target_keyword: p.target_keyword,
  prompt_text: p.prompt_text,
  status: 'Pending scan'
}}));
